&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Gen&amp;ccedil; Saadet&amp;rsquo;ten &amp;Uuml;niversitelerdeki Şiddet ve Yurtlardaki Gıda Skandallarına Tepki: &amp;ldquo;Gen&amp;ccedil;liği Kavgayla Değil, Kardeşlikle B&amp;uuml;y&amp;uuml;tmeliyiz&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;br /&gt;
&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Saadet Partisi Genel Merkez Gen&amp;ccedil;lik Kolları Başkanı Av. Haldun Pekdemir, &amp;ldquo;Haftalık Gen&amp;ccedil;lik G&amp;uuml;ndemi&amp;rdquo; başlığıyla yaptığı basın a&amp;ccedil;ıklamasında, son g&amp;uuml;nlerde &amp;uuml;niversitelerde yaşanan şiddet olayları ve KYK yurtlarındaki gıda skandallarına sert tepki g&amp;ouml;sterdi. A&amp;ccedil;ıklamada, gen&amp;ccedil;lerin huzuru ve g&amp;uuml;venliği i&amp;ccedil;in devletin sorumluluğuna dikkat &amp;ccedil;ekilerek, &amp;ldquo;Bu &amp;uuml;lkenin gen&amp;ccedil;liği bı&amp;ccedil;akla değil, kalemle yol almalıdır.&amp;rdquo; ifadeleri kullanıldı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Cumhuriyet&amp;rsquo;in 102. yıl d&amp;ouml;n&amp;uuml;m&amp;uuml;n&amp;uuml; ve merhum Prof. Dr. Necmettin Erbakan&amp;rsquo;ın doğum g&amp;uuml;n&amp;uuml;n&amp;uuml; kutlayarak konuşmasına başlayan Av. Haldun Pekdemir, &amp;ldquo;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Aziz milletimizin k&amp;uuml;llerinden doğuşu, emperyalizme karşı verilen m&amp;uuml;cadelenin destanı, bağımsızlığımızın, birlik ve beraberliğimizin d&amp;uuml;nya tarihine vurulan m&amp;uuml;hr&amp;uuml; olan istiklal ve istikbalimizin en g&amp;uuml;&amp;ccedil;l&amp;uuml; cephesini, 29 Ekim Cumhuriyet Bayramımızı kutluyorum. Bug&amp;uuml;n hepimizin hatırasına gelen o fotoğraftaki &amp;ldquo;Cumhuriyeti Biz B&amp;ouml;yle Kazandık&amp;rdquo; diyenlere &amp;ccedil;ok şey bor&amp;ccedil;luyuz. Emaneti emanet bilerek yolumuza devam edeceğiz. Dedi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kamp&amp;uuml;slerde &amp;ouml;zg&amp;uuml;rl&amp;uuml;k, adalet ve emniyet bir arada m&amp;uuml;mk&amp;uuml;nd&amp;uuml;r&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;A&amp;ccedil;ıklamada, Hacettepe ve Ankara &amp;Uuml;niversitelerinde yaşanan &amp;ouml;ğrenci &amp;ccedil;atışmalarına değinilerek, &amp;ldquo;&amp;Uuml;niversite &amp;ouml;nlerinde &amp;ouml;ğrenciler g&amp;ouml;rmeye alışığız ama &amp;ccedil;evik kuvvet ve adli tıp uzmanlarını g&amp;ouml;rmeye alışmamalıyız.&amp;rdquo; denildi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Parti, siyaset dilindeki kutuplaşmanın gen&amp;ccedil;ler arasında ideolojik kamplaşmaya neden olduğunu vurgulayarak, &amp;ldquo;Gen&amp;ccedil;leri ideolojik saflara sıkıştırmak yerine aynı masada konuşturmayı başaramazsak, huzuru sadece &amp;ouml;zlemle anarız.&amp;rdquo; değerlendirmesinde bulundu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bir Cani Kamp&amp;uuml;s&amp;uuml;n İ&amp;ccedil;ine Elini Kolunu Sallayarak Nasıl Girebiliyor ?&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kayseri Erciyes &amp;Uuml;niversitesi&amp;rsquo;nde &amp;uuml;&amp;ccedil; &amp;ccedil;ocuk annesi Meliha Keskin&amp;rsquo;in eski eşi tarafından kamp&amp;uuml;s i&amp;ccedil;inde &amp;ouml;ld&amp;uuml;r&amp;uuml;lmesine de değinilen a&amp;ccedil;ıklamada, &amp;ldquo;Bir cani elini kolunu sallayarak kamp&amp;uuml;se silahla girebiliyor. Bu olayın hesabını kim verecek&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Nasıl oluyor da bir cani, elini kolunu sallayarak kamp&amp;uuml;se silahla girebiliyor?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu sorunun cevabını vermek zorundayız. Bunun hesabını kime soracağız?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Uuml;niversite y&amp;ouml;netimi, &amp;ouml;ğrencilere g&amp;ouml;nderdiği toplu mesajda &amp;ldquo;Olay kamp&amp;uuml;s&amp;uuml;m&amp;uuml;z&amp;uuml;n genel g&amp;uuml;venliğini etkilememektedir.&amp;rdquo;diyor.&lt;br /&gt;
Bu s&amp;ouml;zlerimizden dolayı kusurumuza bakabilirsiniz ama Allah aşkına siz neyin g&amp;uuml;venliğinden bahsediyorsunuz?&lt;br /&gt;
Bir &amp;ouml;ğrenciniz pompalı t&amp;uuml;fekle canice katledilirken, almanız gereken &amp;ouml;nlemleri unutturup bizi avutma &amp;ccedil;abanızı mı takdir edeceğiz?Bu memlekette ciddi bir &amp;ldquo;sorumluluktan ka&amp;ccedil;ış&amp;rdquo; ve &amp;ldquo;işini başkasına havale etme&amp;rdquo; krizi vardır.&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;?&amp;rdquo; ifadeleriyle g&amp;uuml;venlik zaafiyetine tepki g&amp;ouml;sterildi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Pekdemir, yetkilileri &amp;ldquo;sorumluluktan ka&amp;ccedil;makla&amp;rdquo; eleştirerek, &amp;ldquo;Koltukların hepsi dolu ama milletine hesap verme cesaretine sahip kimse kalmamış.&amp;rdquo; dedi&lt;strong&gt;.&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;KYK yurtlarında yaşanan hijyen ve gıda g&amp;uuml;venliği sorunlarının da g&amp;uuml;ndeme taşındığı a&amp;ccedil;ıklamada, Denizli ve Tokat&amp;rsquo;taki zehirlenme vakaları hatırlatıldı. Parti, &amp;ldquo;2025 T&amp;uuml;rkiye&amp;rsquo;sinde devletine g&amp;uuml;venen bir aile, &amp;ccedil;ocuğunu yurda emanet ettiğinde karşılaştığı tablo bu mu olmalı?&amp;rdquo; diyerek tepki g&amp;ouml;sterdi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ayrıca Hacettepe &amp;Uuml;niversitesi&amp;rsquo;nin yemekhanelerde başlattığı rezervasyon sistemine eleştiri getirilerek, &amp;ldquo;İsrafla m&amp;uuml;cadele &amp;ouml;ğrencinin omzuna y&amp;uuml;k bindirerek değil, bilimsel y&amp;ouml;ntemlerle yapılmalıdır.&amp;rdquo; denildi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Saadet Partisi Gen&amp;ccedil;lik Kolları olarak &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;ouml;nerilerini de sıralayan Pekdemir,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Uuml;niversitelerde şiddet olaylarına karışan herkes i&amp;ccedil;in adil, hızlı ve şeffaf yargılama s&amp;uuml;reci işletilmeli.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ceza değil,&amp;nbsp;&lt;strong&gt;infaz kanununda caydırıcı d&amp;uuml;zenlemeler&lt;/strong&gt;&amp;nbsp;yapılmalı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Uuml;niversitelerde g&amp;uuml;venlik artırılmalı ancak &amp;ouml;ğrencilerin &amp;ouml;zg&amp;uuml;rl&amp;uuml;k alanları daraltılmamalı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;KYK yurtlarında gıda g&amp;uuml;venliği ve barınma koşulları kamuoyuna a&amp;ccedil;ık şekilde denetlenmelidir, dedi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&amp;nbsp;&lt;/p&gt;
